package com.clavis.reader;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
/** RSS shelves use the same artwork-and-copy rows as the audio shelf. */
final class FeedScreens {

 static void refreshIcon(MainActivity a,String kind,boolean sources){if(kind.equals("News")||kind.equals("Journals"))a.bar.addView(UiStyle.icon(a,R.drawable.ic_refresh_feeds,kind.equals("News")?"Refresh news":"Refresh articles",()->refreshAll(a,kind,sources),48));}
 static void refreshAll(MainActivity a,String kind){refreshAll(a,kind,a.feedSources);}
 static void refreshAll(MainActivity a,String kind,boolean sources){ArrayList<FeedStore.Feed> selected=new ArrayList<>();for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals(kind))selected.add(feed);refresh(a,kind,selected,sources);}
 static String plain(String html){return Html.fromHtml(html,Html.FROM_HTML_MODE_LEGACY).toString().trim();}
 static void tabs(MainActivity a,String kind,boolean sources){a.feedSources=sources;
  LinearLayout panel=a.column();panel.setPadding(a.dp(16),a.dp(6),a.dp(16),a.dp(8));LinearLayout row=a.row();
  String[] labels={"Popular","Sources"};for(int n=0;n<labels.length;n++){final boolean target=n==1;TextView tab=a.button(labels[n],()->show(a,kind,target));boolean selected=target==sources;tab.setSelected(selected);tab.setContentDescription(labels[n]+(selected?", selected tab":", tab"));tab.setTextColor(selected?MainActivity.INK:MainActivity.MUTED);tab.setBackground(selected?UiStyle.surface(a,kind,14):null);row.addView(tab,new LinearLayout.LayoutParams(0,a.dp(48),1));}panel.addView(row);
  if(!sources){TextView note=a.text("Most opened here, then recent picks from each source",12,MainActivity.MUTED,false);note.setPadding(a.dp(6),a.dp(8),a.dp(6),0);panel.addView(note);}a.root.addView(panel,1,new LinearLayout.LayoutParams(-1,-2));
 }
 static void popular(MainActivity a,String kind){
  a.screen=kind;a.shell(kind.equals("Journals")?"Articles":kind);a.bar.removeViewAt(2);
  ArrayList<FeedStore.Feed> saved=FeedStore.load(a);ArticleRepository.prefetch(a,kind,saved);FeedDate.repair(a,kind,saved);
  refreshIcon(a,kind,false);a.bar.addView(UiStyle.icon(a,R.drawable.ic_toolbar_more,"Feed actions",()->new AppDialog.Builder(a).setTitle("Feed actions").setItems(new String[]{"Refresh all sources","Browse sources"},(d,n)->{if(n==1)FeedCatalog.browse(a,kind);else refreshAll(a,kind);}).show(),48));
  FeedStore.Feed combined=FeedHighlights.combined(a,kind,saved);
  if(!kind.equals("Podcasts")&&!combined.items.isEmpty())FeedPosts.attach(a,combined);
  else{for(FeedStore.Item item:combined.items)entry(a,combined.origins.get(item),item);if(combined.items.isEmpty()){a.body.addView(a.text("No entries yet. Add or refresh sources to fill this tab.",16,MainActivity.MUTED,false));a.body.addView(a.button("Browse sources",()->FeedCatalog.browse(a,kind)));}a.miniPlayer();}
  tabs(a,kind,false);
 }
 static void show(MainActivity a,String kind){show(a,kind,false);}
 static void show(MainActivity a,String kind,boolean sources){if(!sources){popular(a,kind);return;}a.screen=kind;a.shell(kind.equals("Journals")?"Articles":kind);a.bar.removeViewAt(2);refreshIcon(a,kind,true);a.bar.addView(UiStyle.icon(a,R.drawable.ic_browser_globe,"Browse "+FeedCatalog.label(kind)+" sources",()->FeedCatalog.browse(a,kind),40));a.bar.addView(UiStyle.icon(a,R.drawable.ic_add,"Add "+FeedCatalog.label(kind)+" RSS feed",()->add(a,kind),34));
  tabs(a,kind,true);a.body.addView(a.button("Search "+FeedCatalog.label(kind).toLowerCase(Locale.ROOT)+" online",()->FeedCatalog.browse(a,kind)));a.space(a.body,8);LinearLayout actions=a.row();TextView add=a.button("Add RSS feed",()->add(a,kind)),manage=a.button("Feeds / refresh",()->manage(a,kind));actions.addView(add,new LinearLayout.LayoutParams(0,a.dp(44),1));actions.addView(manage,new LinearLayout.LayoutParams(0,a.dp(44),1));a.body.addView(actions);a.space(a.body,14);
  ArrayList<FeedStore.Feed> saved=FeedStore.load(a);ArticleRepository.prefetch(a,kind,saved);FeedDate.repair(a,kind,saved);int count=0,subscriptions=0;for(FeedStore.Feed feed:saved)if(feed.kind.equals(kind)){subscriptions++;source(a,feed);count+=feed.items.size();}
  if(count==0){a.space(a.body,35);TextView empty=a.text(subscriptions==0?"Follow your favourite "+kind.toLowerCase(Locale.ROOT):"No entries in your feeds yet",20,MainActivity.INK,true);empty.setGravity(Gravity.CENTER);a.body.addView(empty);a.space(a.body,12);TextView help=a.text("Add an RSS or Atom feed URL. "+(kind.equals("Podcasts")?"Episodes with audio enclosures play in your podcast player.":"New articles appear here with artwork and a summary."),14,MainActivity.MUTED,false);help.setGravity(Gravity.CENTER);a.body.addView(help);}a.miniPlayer();
 }
 static void source(MainActivity a,FeedStore.Feed feed){LinearLayout row=a.row();row.setPadding(a.dp(14),a.dp(14),a.dp(14),a.dp(14));row.setBackground(UiStyle.surface(a,feed.kind,18));ImageView art=FeedIcons.tile(a,feed.title);row.addView(art,new LinearLayout.LayoutParams(a.dp(62),a.dp(62)));FeedArtwork.bindSource(a,art,feed);LinearLayout copy=a.column();TextView title=a.text(plain(feed.title),16,MainActivity.INK,true);title.setTypeface(a.serif,Typeface.BOLD);copy.addView(title);copy.addView(a.text(feed.items.size()+(feed.kind.equals("Podcasts")?" episodes":" articles")+(feed.error.isEmpty()?"":" · Refresh failed"),12,MainActivity.MUTED,false));if(!feed.items.isEmpty()){TextView latest=a.text(plain(feed.items.get(0).title),12,MainActivity.MUTED,false);latest.setMaxLines(2);copy.addView(latest);}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(14);row.addView(copy,cp);row.setContentDescription(feed.title);row.setOnClickListener(v->items(a,feed));a.body.addView(row);a.space(a.body,10);}
 static void items(MainActivity a,FeedStore.Feed selected){FeedStore.Feed feed=selected;for(FeedStore.Feed current:FeedStore.load(a))if(current.kind.equals(selected.kind)&&current.url.equals(selected.url))feed=current;if(!feed.kind.equals("Podcasts")){FeedPosts.show(a,feed);return;}FeedStore.Feed shown=feed;a.screen=feed.kind+" feed";a.shell(feed.title);a.bar.getChildAt(0).setOnClickListener(v->show(a,shown.kind,true));a.bar.removeViewAt(2);a.bar.addView(UiStyle.icon(a,R.drawable.ic_browser_globe,"Browse "+feed.kind+" sources",()->FeedCatalog.browse(a,shown.kind),40));a.body.addView(a.button("Refresh feed",()->refreshSource(a,shown)));a.space(a.body,12);for(FeedStore.Item item:feed.items)entry(a,feed,item);if(feed.items.isEmpty())a.body.addView(a.text("No entries yet. Refresh this feed to check for updates.",14,MainActivity.MUTED,false));a.miniPlayer();}
 static void refreshSource(MainActivity a,FeedStore.Feed feed){refresh(a,feed.kind,new ArrayList<>(Collections.singletonList(feed)));}
 static void add(MainActivity a,String kind){EditText input=new EditText(a);input.setSingleLine();input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);input.setHint("https://example.com/feed.xml");LinearLayout panel=a.column();panel.setPadding(a.dp(20),a.dp(8),a.dp(20),0);panel.addView(input);AlertDialog dialog=new AppDialog.Builder(a).setTitle("Add "+kind+" feed").setView(panel).setPositiveButton("Add",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String url=FeedStore.web(input.getText().toString());if(url.isEmpty()){input.setError("Enter a valid http or https RSS feed URL");return;}dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);input.setEnabled(false);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setText("Loading…");a.io.execute(()->{try{FeedStore.Feed feed=FeedStore.download(url,kind);FeedStore.put(a,feed);a.runOnUiThread(()->{if(a.isDestroyed())return;dialog.dismiss();if(a.screen.equals(kind))show(a,kind);});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;input.setEnabled(true);input.setError(e.getMessage());dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(true);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setText("Add");});}});}));dialog.show();}
 static void manage(MainActivity a,String kind){ArrayList<FeedStore.Feed> feeds=new ArrayList<>();for(FeedStore.Feed f:FeedStore.load(a))if(f.kind.equals(kind))feeds.add(f);ArrayList<String> choices=new ArrayList<>();choices.add("Refresh all feeds");choices.add("Add RSS feed");for(FeedStore.Feed f:feeds)choices.add(f.title);new AppDialog.Builder(a).setTitle(kind+" feeds").setItems(choices.toArray(new String[0]),(d,n)->{if(n==0)refresh(a,kind,feeds);else if(n==1)add(a,kind);else{FeedStore.Feed f=feeds.get(n-2);new AppDialog.Builder(a).setTitle(f.title).setMessage(f.url+(f.error.isEmpty()?"":"\n\n"+f.error)).setPositiveButton("Refresh",(dd,x)->refresh(a,kind,new ArrayList<>(Collections.singletonList(f)))).setNeutralButton("Remove feed",(dd,x)->new AppDialog.Builder(a).setTitle("Remove feed?").setMessage("Remove this subscription and its cached entries? Your saved podcast playback positions are kept.").setPositiveButton("Remove",(ddd,y)->{FeedStore.remove(a,f);show(a,kind);}).setNegativeButton("Cancel",null).show()).setNegativeButton("Close",null).show();}}).setNegativeButton("Close",null).show();}
 static void refresh(MainActivity a,String kind,ArrayList<FeedStore.Feed> feeds){refresh(a,kind,feeds,a.feedSources);}
 static void refresh(MainActivity a,String kind,ArrayList<FeedStore.Feed> feeds,boolean sources){if(feeds.isEmpty()){add(a,kind);return;}ProgressDialog progress=new ProgressDialog(a);progress.setMessage("Refreshing feeds…");progress.setCancelable(false);progress.show();a.io.execute(()->{int failed=0;ArrayList<FeedStore.Feed> refreshed=new ArrayList<>();for(FeedStore.Feed old:feeds)try{FeedStore.Feed updated=FeedStore.download(old.url,old.kind);boolean exists=false;for(FeedStore.Feed current:FeedStore.load(a))if(current.url.equals(old.url)&&current.kind.equals(old.kind))exists=true;if(exists){FeedStore.put(a,updated);refreshed.add(old);refreshed.add(updated);}}catch(Exception e){failed++;old.error=e.getMessage()==null?"Could not refresh feed":e.getMessage();FeedStore.put(a,old);}ArticleRepository.invalidate(a,refreshed);int errors=failed;a.runOnUiThread(()->{if(a.isDestroyed())return;progress.dismiss();if(a.screen.equals(kind))show(a,kind,sources);else if(a.screen.equals(kind+" feed")&&feeds.size()==1)items(a,feeds.get(0));if(errors>0)new AppDialog.Builder(a).setTitle("Feed refresh").setMessage(errors+" feed(s) could not refresh. Saved entries are still available.").setPositiveButton("Close",null).show();});});}
 static void entry(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){LinearLayout row=a.row();row.setPadding(a.dp(14),a.dp(14),a.dp(14),a.dp(14));row.setBackground(UiStyle.surface(a,feed.kind,18));ImageView art=FeedIcons.tile(a,feed.title);row.addView(art,new LinearLayout.LayoutParams(a.dp(62),a.dp(62)));loadArt(a,art,item.image);LinearLayout copy=a.column();TextView title=a.text(plain(item.title),15,MainActivity.INK,true);title.setTypeface(a.serif,Typeface.BOLD);title.setMaxLines(2);copy.addView(title);String meta=item.date;if(a.screen.equals(feed.kind))meta=plain(feed.title)+(meta.isEmpty()?"":" · "+meta);if(feed.kind.equals("Podcasts")&&item.duration>0)meta=Store.time(item.duration)+(meta.isEmpty()?"":" · "+meta);TextView detail=a.text(meta,11,MainActivity.MUTED,false);detail.setMaxLines(1);copy.addView(detail);TextView summary=a.text(plain(item.description),12,MainActivity.MUTED,false);summary.setMaxLines(2);summary.setEllipsize(TextUtils.TruncateAt.END);copy.addView(summary);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.leftMargin=a.dp(14);row.addView(copy,cp);row.setOnClickListener(v->{if(feed.kind.equals("Podcasts")&&!item.audio.isEmpty())play(a,feed,item);else article(a,feed,item);});row.setContentDescription(plain(item.title));a.body.addView(row);a.space(a.body,10);}
 static void loadArt(MainActivity a,ImageView image,String url){FeedArtwork.bind(a,image,url);}

 static void play(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){FeedHighlights.opened(a,item);ArrayList<Book> books=Store.load(a);Book target=null;for(Book b:books)if(b.uri.equals(item.audio)&&b.author.equals("Podcast"))target=b;if(target==null){target=new Book(item.audio,plain(item.title),"Podcast");target.duration=item.duration;target.chaptersChecked=true;books.add(target);}target.coverUri=item.image;Store.save(a,books);a.open(target);}
 static FeedStore.Item adjacent(MainActivity a,Book book,int direction){for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts")){ArrayList<FeedStore.Item> episodes=new ArrayList<>();for(FeedStore.Item item:feed.items)if(!item.audio.isEmpty())episodes.add(item);for(int i=0;i<episodes.size();i++)if(episodes.get(i).audio.equals(book.uri)){int at=i+direction;return at>=0&&at<episodes.size()?episodes.get(at):null;}}return null;}
 static void nextEpisode(MainActivity a,Book book,int direction){FeedStore.Item next=adjacent(a,book,direction);if(next==null)return;for(FeedStore.Feed feed:FeedStore.load(a))if(feed.kind.equals("Podcasts"))for(FeedStore.Item item:feed.items)if(item.audio.equals(next.audio)){play(a,feed,item);return;}}
 static void article(MainActivity a,FeedStore.Feed feed,FeedStore.Item item){FeedHighlights.opened(a,item);if(!item.link.isEmpty()){a.startActivity(new Intent(a,ArticleActivity.class).putExtra("url",item.link).putExtra("title",plain(item.title)).putExtra("summary",item.description).putExtra("image",item.image));return;}a.screen=feed.kind+" article";a.shell(feed.kind);a.bar.getChildAt(0).setOnClickListener(v->show(a,feed.kind));TextView title=a.text(plain(item.title),25,MainActivity.INK,true);a.body.addView(title);a.space(a.body,10);a.body.addView(a.text(feed.title+" · "+item.date,12,MainActivity.MUTED,false));if(!item.image.isEmpty()){ImageView art=new ImageView(a);art.setScaleType(ImageView.ScaleType.FIT_CENTER);a.body.addView(art,new LinearLayout.LayoutParams(-1,a.dp(180)));loadArt(a,art,item.image);}a.space(a.body,14);TextView text=a.text(plain(item.description),18,MainActivity.INK,false);text.setLineSpacing(a.dp(5),1.1f);text.setTextIsSelectable(true);a.body.addView(text);if(item.description.isEmpty())a.body.addView(a.text("This feed does not include article text. Open the source to read it.",14,MainActivity.MUTED,false));a.space(a.body,20);if(!item.link.isEmpty())a.body.addView(a.button("Read on website",()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(item.link)))));if(!item.document.isEmpty())a.body.addView(a.button("Open attached PDF",()->openPdf(a,item.document,item.title)));}
 static void openPdf(MainActivity a,String url,String title){ProgressDialog wait=new ProgressDialog(a);wait.setMessage("Opening PDF…");wait.setCancelable(false);wait.show();a.io.execute(()->{try{byte[] bytes=FeedStore.fetch(url,64*1024*1024);java.io.File file=java.io.File.createTempFile("journal-",".pdf",a.getCacheDir());try(java.io.OutputStream out=new java.io.FileOutputStream(file)){out.write(bytes);}a.runOnUiThread(()->{if(a.isDestroyed())return;wait.dismiss();a.startActivity(new Intent(a,ReaderActivity.class).putExtra("uri",Uri.fromFile(file).toString()).putExtra("kind","PDF").putExtra("title",plain(title)));});}catch(Exception e){a.runOnUiThread(()->{if(a.isDestroyed())return;wait.dismiss();new AppDialog.Builder(a).setTitle("PDF attachment").setMessage(e.getMessage()).setPositiveButton("Close",null).show();});}});}
}





